local function lookup(ranges,cp,default)
  local lo,hi=1,#ranges
  while lo<=hi do
    local m=math.floor((lo+hi)/2);local r=ranges[m]
    if cp<r[1] then hi=m-1 elseif cp>r[2] then lo=m+1 else return r[3] or true end
  end
  return default
end
function P.line_break(cp) return lookup(lb,tonumber(cp) or -1,"XX") end
function P.east_asian(cp) return lookup(eaw,tonumber(cp) or -1,"N") end
function P.is_initial_punctuation(cp) return lookup(pi,tonumber(cp) or -1,false)==true end
function P.is_final_punctuation(cp) return lookup(pf,tonumber(cp) or -1,false)==true end
function P.is_extended_pictographic(cp) return lookup(ep,tonumber(cp) or -1,false)==true end
return P
